}

import Link from "next/link";

const posts = [
  { slug: "hello-nextjs", title: "Hello Next.js" },
  { slug: "routing-basics", title: "Routing basics" },
];

export default function BlogPage() {
  return (
    <ul>
      {posts.map((p) => (
        <li key={p.slug}>
          <Link href={`/blog/${p.slug}`}>{p.title}</Link>
        </li>
      ))}
    </ul>
  );
}

export function generateStaticParams() {
  return [{ slug: "hello-nextjs" }, { slug: "routing-basics" }];
}

export default async function PostPage({ params }: PageProps<"/blog/[slug]">) {
  const { slug } = await params;
  return <h1>Post: {slug}</h1>;
}

export default async function ProductPage({ params }: PageProps<"/shop/[category]/[product]">) {
  const { category, product } = await params;
  return <p>{category} / {product}</p>;
}

import { Suspense } from "react";

async function Parts({ params }: { params: PageProps<"/shop/[...slug]">["params"] }) {
  const { slug } = await params; // always an array, for example ["shoes", "running"]
  return <p>Path parts: {slug.join(" / ")}</p>;
}

export default function ShopPage(props: PageProps<"/shop/[...slug]">) {
  return (
    <Suspense fallback={<p>Loading...</p>}>
      <Parts params={props.params} />
    </Suspense>
  );
}

import { Suspense } from "react";

async function Doc({ params }: { params: PageProps<"/docs/[[...slug]]">["params"] }) {
  const { slug } = await params; // undefined on /docs itself
  return <p>{slug ? `Doc: ${slug.join("/")}` : "Docs home"}</p>;
}

export default function DocsPage(props: PageProps<"/docs/[[...slug]]">) {
  return (
    <Suspense fallback={<p>Loading...</p>}>
      <Doc params={props.params} />
    </Suspense>
  );
}

import Card from "../../_components/Card";

