"use client";

import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";

export default function NavLinks() {
  const pathname = usePathname();
  const router = useRouter();
  const links = [
    { href: "/", label: "Home" },
    { href: "/about", label: "About" },
    { href: "/blog", label: "Blog" },
  ];
  return (
    <nav className="flex gap-4">
      {links.map((l) => (
        <Link key={l.href} href={l.href} className={pathname === l.href ? "font-bold" : ""}>
          {l.label}
        </Link>
      ))}
      <button onClick={() => router.push("/pricing")}>See pricing</button>
    </nav>
  );
}

"use client";

import { useSearchParams } from "next/navigation";

export default function SearchBox() {
  const params = useSearchParams();
  const q = params.get("q") ?? "";
  return <p>You searched for: {q || "nothing yet"}</p>;
}

"use client";

import { usePathname, useRouter, useSearchParams } from "next/navigation";

export default function SortButton() {
  const pathname = usePathname();
  const router = useRouter();
  const searchParams = useSearchParams();

  function sortBy(value: string) {
    const next = new URLSearchParams(searchParams.toString());
    next.set("sort", value);
    router.push(`${pathname}?${next.toString()}`);
  }

  return <button onClick={() => sortBy("price")}>Sort by price</button>;
}

import { redirect } from "next/navigation";

export default function OldPage() {
